<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit;
require __DIR__.'/../app/autoload.php';use App\Core\{Auth,Database as DB};use App\Services\{ManagementService as M,QuestionImportService as Import};
$pdo=DB::pdo();$pdo->beginTransaction();$passed=0;$files=[];
function qiCheck(bool $v,string $label): void {global $passed;if(!$v)throw new RuntimeException('FAIL '.$label);echo 'PASS '.$label.PHP_EOL;$passed++;}
function qiReject(callable $f,string $label): void {try{$f();}catch(DomainException|InvalidArgumentException $e){qiCheck(true,$label);return;}throw new RuntimeException('FAIL '.$label);}
function qiAs(int $id): void {$_SESSION=['uid'=>$id,'last_activity'=>time()];foreach(['loaded'=>false,'user'=>null] as $k=>$v)(new ReflectionProperty(Auth::class,$k))->setValue(null,$v);}
try{
    $root=(int)DB::val("SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE r.code='super_admin' AND u.status='active' AND u.deleted_at IS NULL LIMIT 1");qiAs($root);
    $a=M::save('subjects',null,['code'=>'QA-IMPORT-A','name'=>'QA Import A','is_active'=>1]);$b=M::save('subjects',null,['code'=>'QA-IMPORT-B','name'=>'QA Import B','is_active'=>1]);
    $md=['subject_id'=>$a,'code'=>'IMPORT-M','week_no'=>1,'sequence_no'=>1,'estimated_minutes'=>10,'status'=>'published','title_en'=>'Excel Module','title_hi'=>'एक्सेल मॉड्यूल','description_en'=>'','description_hi'=>''];$module=M::save('modules',null,$md);$md['subject_id']=$b;$foreign=M::save('modules',null,$md);
    $rows=Import::read(APP_ROOT.'/storage/templates/question-bank-sample.xlsx','sample.xlsx');qiCheck(count($rows)===2&&$rows[1]['correct_option']==='C','actual sample XLSX reads English/Hindi and answer keys');
    $result=Import::import($a,$module,$rows);qiCheck($result===['created'=>2,'skipped'=>0],'two questions imported to selected subject/module');qiCheck((int)DB::val('SELECT COUNT(*) FROM question_options o JOIN questions q ON q.id=o.question_id WHERE q.subject_id=?',[$a])===8,'four answer options stored for each imported question');
    qiCheck(Import::import($a,$module,$rows)===['created'=>0,'skipped'=>2],'re-import skips duplicates without overwriting');
    $bad=$rows;$bad[0]['question_en']='New row that must roll back';$bad[1]['question_en']='Bad answer';$bad[1]['correct_option']='Z';qiReject(fn()=>Import::import($a,$module,$bad),'invalid row rejects entire import');qiCheck((int)DB::val('SELECT COUNT(*) FROM questions WHERE subject_id=?',[$a])===2,'earlier rows rolled back atomically');
    qiReject(fn()=>Import::import($a,$foreign,$rows),'cross-subject module denied');qiReject(fn()=>Import::import($a,$module,array_fill(0,501,$rows[0])),'question limit enforced');
    $csv=APP_ROOT.'/tmp/question-import-test.csv';$files[]=$csv;$h=fopen($csv,'wb');fputcsv($h,Import::HEADERS,',','"','');foreach($rows as $r)fputcsv($h,array_values($r),',','"','');fclose($h);qiCheck(count(Import::read($csv,'questions.csv'))===2,'UTF-8 CSV supported');
    file_put_contents($csv,'wrong,headers');qiReject(fn()=>Import::read($csv,'questions.csv'),'unexpected headers rejected');file_put_contents($csv,str_repeat('x',2097153));qiReject(fn()=>Import::read($csv,'large.xlsx'),'oversized spreadsheet rejected');
    $zipPath=APP_ROOT.'/tmp/question-import-formula.xlsx';$files[]=$zipPath;copy(APP_ROOT.'/storage/templates/question-bank-sample.xlsx',$zipPath);$z=new ZipArchive();$z->open($zipPath);$xml=$z->getFromName('xl/worksheets/sheet1.xml');$xml=preg_replace('/(<(?:\w+:)?c\b[^>]*\br="A2"[^>]*>)/','$1<f xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">1+1</f>',$xml,1);$z->addFromString('xl/worksheets/sheet1.xml',$xml);$z->close();qiReject(fn()=>Import::read($zipPath,'formula.xlsx'),'Excel formulas rejected');
    $td=['title'=>'','title_hi'=>'','subject_id'=>$a,'module_id'=>$module,'test_type'=>'practice','week_no'=>1,'duration_minutes'=>0,'pass_percent'=>50,'pass_rule'=>'gte','max_attempts'=>'','retake_wait_hours'=>0,'min_study_percent'=>0,'status'=>'draft','question_ids'=>[]];$test=M::save('tests',null,$td);qiCheck(DB::val('SELECT title FROM tests WHERE id=?',[$test])==='QA Import A — Excel Module','server generates editable default test title from subject/module');
    $td['title']='Custom title';$td['title_hi']='बदला शीर्षक';M::save('tests',$test,$td);qiCheck(DB::val('SELECT title FROM tests WHERE id=?',[$test])==='Custom title','custom edited test title retained');
    $teacher=M::save('users',null,['full_name'=>'QA Import Teacher','username'=>'qa.import.teacher','role_id'=>DB::val("SELECT id FROM roles WHERE code='teacher'"),'password'=>'QaTest@2026!','status'=>'active']);M::save('assignments',null,['teacher_id'=>$teacher,'subject_id'=>$a,'can_manage_tests'=>1]);qiAs($teacher);
    qiReject(fn()=>Import::import($b,$foreign,$rows),'Teacher cannot import into foreign subject');$one=$rows[0];$one['question_en']='Teacher owned import';qiReject(fn()=>Import::import($a,$module,[$one]),'subject grant without batch cannot authorize import');qiAs($root);
    $centre=M::save('centres',null,['name'=>'QA Import Centre','is_active'=>1]);$batch=M::save('batches',null,['name'=>'QA Import Batch','centre_id'=>$centre,'training_mode'=>'community','is_active'=>1]);DB::run('UPDATE users SET centre_id=? WHERE id=?',[$centre,$teacher]);M::save('centre_subjects',null,['centre_id'=>$centre,'subject_id'=>$a]);$course=\App\Services\CourseAssignmentService::saveCourse(null,'QA-IMPORT-COURSE','QA Import Course');\App\Services\CourseAssignmentService::setCourseSubject($course,$a);\App\Services\CourseAssignmentService::setCentreCourse($centre,$course);\App\Services\CourseAssignmentService::setBatchCourse($batch,$course);\App\Services\CourseAssignmentService::setBatchSubjects($batch,$course,[$a]);\App\Services\CourseAssignmentService::setTeacherAssignment($teacher,$batch,$course,$a);qiAs($teacher);
    qiCheck(Import::import($a,$module,[$one])['created']===1,'Teacher with explicit batch and tests grant can import assigned subject');
    echo "$passed question import checks passed; fixtures rolled back.\n";
}finally{if($pdo->inTransaction())$pdo->rollBack();foreach($files as $p)if(is_file($p))unlink($p);}
